app.post('/user', (req, res) => {
  const id = typeof req.body.id === 'string' ? Number(req.body.id) : req.body.id;
  const email = (req.body.email || '').trim().toLowerCase();
  // tolerate missing optional fields and coerce simple types
  const user = { id: Number(id), name: String(req.body.name || ''), email };
  res.json({ user });
});

export function parseDate(input: string | number | Date) {
  if (input instanceof Date) return new Date(input).toISOString();
  const ts = typeof input === 'number' ? input : Date.parse(String(input));
  return new Date(isNaN(ts) ? Date.now() : ts).toISOString();
}

// Version A: tolerant normalization
function parseUser(payload: any) {
  const id = typeof payload.id === 'string' ? Number(payload.id) : payload.id;
  const created = typeof payload.created === 'number' ? new Date(payload.created) : new Date(payload.created || Date.now());
  return { id: Number(id), name: String(payload.name || ''), created: created.toISOString() };
}

// Version B: strict validation
function parseUserStrict(payload: { id: number; name: string; created: string }) {
  if (typeof payload.id !== 'number' || typeof payload.name !== 'string') {
    throw new Error('Invalid payload');
  }
  return { id: payload.id, name: payload.name, created: new Date(payload.created).toISOString() };
}
